UsersTable = {}ConnectedPlayers = {}function UsersTable.EnterCharacter(aIndex)	local found = false    for _, index in ipairs(ConnectedPlayers) do        if index == aIndex then            found = true            break        end    end	    if not found then        table.insert(ConnectedPlayers, aIndex)    endendfunction UsersTable.CloseCharacter(aIndex)    for i, index in ipairs(ConnectedPlayers) do        if index == aIndex then            table.remove(ConnectedPlayers, i)            break        end    endendfunction UsersTable.Refresh()    for aIndex = OBJECT_START_USER, MAX_OBJECT do        local player = User.new(aIndex)        if player:getConnected() == 3 then            table.insert(ConnectedPlayers, aIndex)        end        player = nil	endendfunction UsersTable.Init()   UsersTable.Refresh()   GameServerFunctions.PlayerLogout(UsersTable.CloseCharacter)   GameServerFunctions.EnterCharacter(UsersTable.EnterCharacter)endUsersTable.Init()return UsersTable